"""Record verified CPU dependencies without calling them a GPU implementation."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
p=ROOT/'research/boss-gpu-integration-notes.json';r=json.loads(p.read_text(encoding='utf-8'))
r['status']='v33 native80/long4/lifecycle4 and normal API passed; PTX and normal regression still verifying. v32 remains the last full checkpoint.'
r['current_boundary']['gpu_compiler']='core/move/idle/groggy/buff/attack, real enemy-caster definitions, live stealth/taunt/undying/invincible/shared-damage/cover-HP/decoy carriers; true lethal transition returns explicit UnsupportedDetail.'
r['current_boundary']['gpu_world']='Per-squad GPU clock selects authored shots and targets using a separate boss MT19937 stream. Every-frame HP/cover and incoming-hit traces are read-only witnesses, never CPU-simulated inputs.'
refs=[]
for path,n in [('research/detail-down-revive-cpu-reference.json',8),('research/detail-down-continuations-cpu-reference.json',6),('research/detail-down-weapon-modes-cpu-reference.json',4)]:
 c=json.loads((ROOT/path).read_text(encoding='utf-8'));assert c['cpu_reference_verified'] and not c['gpu_implemented'] and len(c['cases'])==n
 assert all(hashlib.sha256((ROOT/f).read_bytes()).hexdigest()==h for f,h in c['source_sha256'].items())
 refs.append(dict(report=path,cases=n,gpu_implemented=False))
r['down_revive_cpu_groundwork']=refs
r['next_required_work']=[dict(area='Actual down/revive runtime',requirements=['On a lethal hit, log the hit before down cleanup; notify self_down after cleanup, then snapshot living allies for ally_down notifications.','Remove received buffs except persist_on_revive, retain buffs given to others, record lost permanent definitions in insertion order, reset personal gauges/stacks/counters while retaining trigger budgets and global counters.','Pre-cast DOT and instant timers continue after caster down. Ordinary every triggers and new skills stop; global-ammo counters advance while their owner is down.','Revive restores eligible passive buffs without double-stacking shared carriers, excludes previously lazy-ranked recipients from unconditional re-addition, suppresses HP-edge transitions while restoring HP, resets actions and refills the magazine.','Port down-aware all/slot/random/rank/compound targets, burst eligibility, control ownership, normal fire, delayed damage and team hit notifications; test raw revival characters and full squads.']),dict(area='Remaining incoming worlds and survival effects',requirements=['Attack-attached debuffs, enemy debuff/DOT patterns, HP-edge triggers, cover controls and cover revival, healing/storage/splitting, and every actual unsupported special effect.','Resolve legacy incoming modifier omissions instead of classifying equal omissions as game correctness.']),dict(area='Remaining boss worlds',requirements=['Interrupt/targets-cleared, coordinate geometry and moving targets, shields/vanish/summons and associated enemy-target effects.']),dict(area='Full completion',requirements=['Every current character/favorite/equipment context without omitted source definitions, and independent whole-squad/event-order acceptance.','Resolve pinned upstream data/model omissions, confirm current catalog coverage, execute in the normal application, and keep scope distinct from a speedup claim.'])]
p.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Eighteen CPU survival references recorded; actual down/revive GPU runtime remains unimplemented.')
